window.QUIZ = {"1": [{"a": 2, "o": ["Đảm bảo lợi nhuận ngắn hạn cho mọi sản phẩm mới", "Trực tiếp làm tăng giá cổ phiếu của doanh nghiệp", "Giúp doanh nghiệp thích nghi khi đối thủ cạnh tranh thay đổi nền tảng/quy luật cạnh tranh", "Chủ yếu chỉ là một khẩu hiệu văn hóa mà không có tác động thực tiễn"], "q": "Tại sao đổi mới sáng tạo (innovation) được xem là yếu tố sống còn đối với sự tồn tại của doanh nghiệp?"}, {"a": 3, "o": ["Nhấn mạnh nhu cầu thị trường là động lực duy nhất của đổi mới sáng tạo", "Nhấn mạnh thay đổi công nghệ là yếu tố ngoại sinh và mang tính ngẫu nhiên", "Nhấn mạnh chi tiêu cho R&D (Nghiên cứu & Phát triển) cấp quốc gia là động lực tăng trưởng trực tiếp", "Nhấn mạnh vào các hoạt động nội bộ và sự khác biệt giữa các doanh nghiệp"], "q": "Thay đổi trọng tâm chính của các nghiên cứu về đổi mới sáng tạo trong giai đoạn đầu thời kỳ hậu chiến là gì?"}, {"a": 2, "o": ["Cấu trúc tổ chức; Kỹ năng nhân viên; Quan hệ với nhà cung cấp", "Đầu vào khoa học và công nghệ; Đầu ra phát triển sản phẩm; Nhu cầu khách hàng và tín hiệu thị trường", "Các cá nhân sáng tạo; Các chức năng và hoạt động vận hành của doanh nghiệp; Cấu trúc doanh nghiệp và các liên kết bên ngoài", "Các cá nhân sáng tạo; Phòng thí nghiệm và quy trình R&D; Nhu cầu thị trường và quy định pháp luật"], "q": "Ba yếu tố nào được trình bày là các thành phần giao thoa, tương tác lẫn nhau và đóng vai trò trung tâm trong quá trình đổi mới sáng tạo?"}, {"a": 1, "o": ["Đổi mới gián đoạn luôn vượt trội về mặt công nghệ; đổi mới duy trì là những cập nhật nhỏ theo định hướng thị trường", "Đổi mới gián đoạn tạo ra thị trường mới và có thể chưa đáp ứng ngay nhu cầu của khách hàng hiện tại; đổi mới duy trì cải tiến sản phẩm cho khách hàng hiện tại", "Đổi mới gián đoạn là những cải tiến nhỏ mang tính tiệm tiến; đổi mới duy trì là những thay đổi mang tính triệt để", "Đổi mới gián đoạn cải tiến sản phẩm cho khách hàng hiện tại; đổi mới duy trì tạo ra thị trường mới"], "q": "Phát biểu nào phân biệt chính xác nhất giữa đổi mới mang tính đột phá/gián đoạn (disruptive innovation) và đổi mới duy trì (sustaining innovation)?"}, {"a": 0, "o": ["Vì chúng đòi hỏi sự kết hợp nhiều nguồn lực như kiến thức, kỹ năng, tài chính và kinh nghiệm thị trường", "Vì chúng chủ yếu là thành quả của những nhà phát minh đơn độc làm việc độc lập", "Vì chúng nảy sinh chủ yếu từ các doanh nghiệp hoạt động hoàn toàn biệt lập với các bên khác", "Vì chúng chỉ cần nguồn vốn nhỏ và có thể được phát triển bởi các công ty gia đình quy mô siêu nhỏ"], "q": "Tại sao các đổi mới sáng tạo quan trọng ngày nay lại gắn liền mật thiết với các tổ chức/doanh nghiệp?"}, {"a": 1, "o": ["Cả nhân viên và nhà quản lý đều thực hiện việc tạo ra ý tưởng và phân bổ nguồn lực như nhau", "Nhân viên tạo ra ý tưởng, xác định vấn đề và hình thành các liên kết sáng tạo; nhà quản lý quyết định các hoạt động và phân bổ nguồn lực", "Nhân viên triển khai đổi mới và phân bổ nguồn lực; nhà quản lý khởi xướng ý tưởng và tạo ra các liên kết sáng tạo", "Nhân viên tập trung vào chiến lược thị trường và cạnh tranh; nhà quản lý chỉ tập trung vào phát minh kỹ thuật"], "q": "Câu nào mô tả đúng nhất vai trò điển hình của nhân viên thông thường so với nhà quản lý trong quy trình đổi mới sáng tạo của một tổ chức?"}, {"a": 2, "o": ["Một thứ chỉ được đánh giá thông qua thành công về mặt thương mại", "Đồng nhất với một phát minh hoặc đơn thuần chỉ là một ý tưởng mới", "Một chuỗi tiến trình từ khám phá mới thông qua phát minh cho đến khi tạo ra sản phẩm thương mại", "Một sự kiện sáng tạo đơn lẻ tạo ra ngay một sản phẩm hoàn chỉnh"], "q": "Câu nào mô tả đúng nhất về đổi mới sáng tạo khi được nhìn nhận dưới góc độ là một quá trình (process)?"}, {"a": 3, "o": ["Phát minh là bất kỳ thay đổi nào về quản lý hoặc tổ chức; đổi mới sáng tạo chỉ là một sản phẩm vật chất", "Phát minh xảy ra khi một ý tưởng có vẻ mới đối với ai đó; đổi mới sáng tạo đòi hỏi ý tưởng đó phải mới một cách khách quan theo thời gian", "Phát minh là việc tung sản phẩm ra thị trường; đổi mới sáng tạo là khám phá khoa học ban đầu", "Phát minh là việc hình thành nên một ý tưởng; đổi mới sáng tạo là việc chuyển hóa ý tưởng đó thành ứng dụng thương mại và quản trị quá trình liên quan"], "q": "Phát biểu nào phân biệt rõ nhất giữa phát minh (invention) và đổi mới sáng tạo (innovation)?"}, {"a": 3, "o": ["Việc giới thiệu các cấu trúc tổ chức nội bộ mới", "Việc cung cấp các dịch vụ mới dựa trên nền tảng internet", "Việc phát triển một quy trình sản xuất mới", "Việc phát triển một sản phẩm mới hoặc cải tiến sản phẩm hiện có"], "q": "Lựa chọn nào định nghĩa đúng nhất về đổi mới sản phẩm (product innovation)?"}, {"a": 2, "o": ["Chỉ riêng bộ phận Marketing khởi xướng ý tưởng và định hướng R&D theo chuỗi định hướng thị trường", "Một trình tự tuyến tính nghiêm ngặt từ R&D đến thị trường với một thị trường tiếp nhận thụ động", "Sự tương tác qua lại giữa thị trường, nền tảng khoa học và năng lực của doanh nghiệp cùng với các luồng thông tin và phản hồi", "Thay đổi kiến trúc sản phẩm mà không làm thay đổi các công nghệ cấu thành"], "q": "Đặc điểm nào mô tả đúng nhất về mô hình đổi mới tương tác (interactive model of innovation)?"}], "2": [{"a": 0, "o": ["Can thiệp chiến lược vào cơ sở hạ tầng, năng lực công nghệ và nguồn nhân lực", "Chỉ tập trung vào các chính sách điều tiết và tái phân phối", "Chỉ dựa vào việc bắt chước các công nghệ nước ngoài", "Thu hẹp sự tham gia của nhà nước xuống chỉ còn tự do hóa thị trường và các ưu đãi ngắn hạn"], "q": "Hành động nào của nhà nước được xem là quan trọng nhất giúp các quốc gia công nghiệp hóa muộn xây dựng năng lực công nghệ?"}, {"a": 1, "o": ["Đổi mới sáng tạo chỉ được xem xét như một vấn đề nội bộ của tổ chức", "Chúng được nhìn nhận là gắn liền và đan xen trong các thể chế xã hội và chính trị", "Chúng được thúc đẩy chủ yếu bởi các cơ hội mang lại lợi nhuận cao trong ngắn hạn", "Công nghệ phát triển độc lập, tách rời khỏi bối cảnh xã hội và thể chế"], "q": "Phát biểu nào mô tả đúng nhất việc nhìn nhận các quá trình kinh tế trong tính chỉnh thể về mặt xã hội và chính trị?"}, {"a": 1, "o": ["Trợ cấp cho R&D để giảm thiểu rủi ro đầu tư của doanh nghiệp", "Xây dựng đường sá và cung cấp điện năng", "Phổ biến các kết quả nghiên cứu thông qua các phòng thí nghiệm công lập", "Thiết lập các tiêu chuẩn quốc gia về môi trường và an toàn"], "q": "Lựa chọn nào là ví dụ điển hình nhất cho vai trò của nhà nước trong việc cung cấp các tài sản bổ trợ (complementary assets) cho đổi mới sáng tạo?"}, {"a": 3, "o": ["Thúc đẩy độc quyền thông qua việc nới lỏng quy định cạnh tranh", "Loại bỏ các trường đại học khỏi hoạt động nghiên cứu", "Hạn chế các chương trình giáo dục và đào tạo lực lượng lao động", "Trực tiếp tài trợ cho R&D và đóng vai trò là khách hàng mua sắm lớn"], "q": "Đâu là một trong những cách thức chủ yếu để chính phủ một quốc gia trực tiếp thúc đẩy đổi mới công nghệ?"}, {"a": 3, "o": ["Để ở gần các thị trường tiêu dùng hơn", "Để nhận được các ưu đãi thuế và trợ cấp", "Để hưởng lợi từ các ràng buộc pháp lý lỏng lẻo hơn", "Để tiếp cận tri thức mới và các kỹ năng chuyên môn ngách"], "q": "Bên cạnh lý do chi phí nhân công thấp, tại sao các doanh nghiệp lại chuyển hoạt động nghiên cứu và phát triển ra nước ngoài (offshore R&D)?"}, {"a": 3, "o": ["Làm giảm đầu tư đồng đều ở tất cả các doanh nghiệp", "Làm tăng đầu tư vào đổi mới sáng tạo ở hầu hết các doanh nghiệp", "Ít hoặc không có tác động đến đầu tư đổi mới sáng tạo", "Nhìn chung làm sụt giảm mức đầu tư cho đổi mới sáng tạo của các doanh nghiệp"], "q": "Tác động điển hình của một cuộc khủng hoảng kinh tế đối với hoạt động đầu tư vào đổi mới sáng tạo của các doanh nghiệp là gì?"}, {"a": 2, "o": ["Các trường đại học, xã hội dân sự và các nhà đầu tư tư nhân", "Các trường đại học, ngành công nghiệp (doanh nghiệp) và người tiêu dùng", "Các trường đại học (viện nghiên cứu), ngành công nghiệp (doanh nghiệp) và chính phủ", "Ngành công nghiệp, chính phủ và các tổ chức phi lợi nhuận"], "q": "Ba khu vực/thành phần nào được mô tả là có sự tương tác với nhau để thúc đẩy đổi mới sáng tạo (mô hình Triple Helix)?"}, {"a": 3, "o": ["Một thị trường nội địa được bảo hộ với sự cạnh tranh yếu và lợi nhuận độc quyền", "Lợi nhuận ngắn hạn cao và các xu hướng mang tính cơ hội", "Sự thay đổi quy định thường xuyên và sự bất ổn của thị trường", "Sự ổn định kinh tế vĩ mô, nguồn lực dư dả (dự phòng) và tầm nhìn dài hạn"], "q": "Điều kiện nào tạo thuận lợi trực tiếp nhất cho các doanh nghiệp đầu tư vào công nghệ dài hạn và nghiên cứu cơ bản (basic R&D)?"}, {"a": 0, "o": ["Làm điều gì đó khác biệt và kiên trì theo đuổi bất chấp sự phản kháng", "Thích nghi với thế giới thông qua các hoạt động mang tính thói quen lặp lại", "Bắt đầu thành lập và vận hành một doanh nghiệp mới", "Quản lý các công ty đã ổn định mà không chấp nhận rủi ro"], "q": "Phát biểu nào nắm bắt đúng nhất bản chất của tinh thần khởi nghiệp kinh doanh (entrepreneurship)?"}, {"a": 2, "o": ["Hoạt động chủ yếu như một yếu tố sản xuất thứ tư giống như đất đai hoặc vốn", "Chỉ tập trung vào việc phát minh ra các sản phẩm hoặc công nghệ mới", "Nhận diện cơ hội, tổ chức các nguồn lực cần thiết để khai thác và hiện thực hóa cơ hội đó", "Quản lý các nguồn lực hiện có mà không tìm kiếm các cơ hội bên ngoài"], "q": "Câu nào mô tả đúng nhất vai trò cốt lõi của một doanh nhân khởi nghiệp (entrepreneur)?"}], "3": [{"a": 3, "o": ["Chỉ là nhà điều tiết thị trường, không phải nhà phát triển hay người mua", "Nhà cung cấp vốn đầu tư mạo hiểm duy nhất cho các công ty khởi nghiệp", "Người quan sát thụ động trong các quyết định chính sách đổi mới", "Nhà điều tiết (ban hành luật/chính sách), nhà nghiên cứu và người mua sắm các sản phẩm đổi mới sáng tạo"], "q": "Đâu là vai trò mà chính phủ có thể đảm nhận trong quản trị đổi mới sáng tạo?"}, {"a": 0, "o": ["Tính mới (Novelty), Sự triển khai (Implementation), Tác động (Impact)", "Tính mới (Novelty), Sự triển khai (Implementation), Sự chấp nhận (Adoption)", "Tính khả thi (Feasibility), Sự triển khai (Implementation), Tác động (Impact)", "Tính mới (Novelty), Sự lan tỏa (Diffusion), Kết quả đầu ra (Outcome)"], "q": "Ba khía cạnh nào đặc trưng cho các đổi mới sáng tạo được thực thi bởi chính phủ?"}, {"a": 0, "o": ["Sử dụng chatbot để phản hồi các khiếu nại/kiến nghị của người dân", "Kiểm soát biên giới tự động bằng nhận diện khuôn mặt", "Xử lý hoàn thuế tự động bằng AI", "Ứng dụng cảnh sát dự đoán để phân bổ tuần tra"], "q": "Đâu là một ví dụ về việc ứng dụng AI (Trí tuệ nhân tạo) trong khu vực công?"}, {"a": 2, "o": ["Định hướng sản phẩm là chủ đạo (Product dominant)", "Tập trung vào R&D và bằng sáng chế", "Định hướng dịch vụ là chủ đạo (Service dominant)", "Phát triển sản phẩm vì mục tiêu lợi nhuận"], "q": "Phát biểu nào mô tả đúng nhất bản chất chủ đạo của đổi mới sáng tạo trong khu vực công?"}, {"a": 1, "o": ["Chỉ ban hành các đạo luật hoặc quy định mới", "Kết hợp các yếu tố từ nhiều loại hình đổi mới sáng tạo khác nhau", "Dễ dàng phân loại vào một loại hình đổi mới duy nhất", "Được thực hiện hoàn toàn bởi các nhà thầu tư nhân"], "q": "Đặc điểm nào mô tả đúng nhất một đổi mới sáng tạo lai (hybrid innovation) trong khu vực công?"}, {"a": 0, "o": ["Hình thành ý tưởng (Idea generation), Đánh giá (Evaluation), Hiện thực hóa (Realisation)", "Thiết lập chương trình nghị sự, Ghép nối, Thường quy hóa", "Hình thành ý tưởng, Phát triển, Ra mắt", "Xác định vấn đề, Thử nghiệm, Nhân rộng quy mô"], "q": "Ba giai đoạn chính nào tạo nên quy trình đổi mới dịch vụ mới tuần tự?"}, {"a": 0, "o": ["Chuẩn bị các phương án triển khai diện rộng và duy trì bền vững", "Ra mắt toàn diện tại nhiều địa điểm khác nhau", "Lập kế hoạch nhân rộng quy mô và chuyển giao sang các bối cảnh khác", "Thiết kế và tạo mẫu thử (prototyping) các giải pháp mới"], "q": "Câu nào mô tả đúng nhất vai trò của giai đoạn \"Kế hoạch triển khai và duy trì\" (Implementation and sustainment plan) ngay sau bước \"Thử nghiệm & thí điểm\" (Testing & piloting)?"}, {"a": 1, "o": ["Trả lương theo hiệu suất và các mục tiêu quản lý", "Quản trị mạng lưới và kết nối xuyên ranh giới (Network management and boundary spanning)", "Tư nhân hóa và thuê ngoài (contracting out)", "Thực thi dựa trên quy tắc thứ bậc hành chính"], "q": "Đâu là một công cụ chính cho quản trị công theo mạng lưới đa bên liên quan (multi-stakeholder, networked public governance)?"}, {"a": 0, "o": ["Tái định nghĩa / Tái cấu trúc (Redefining/restructuring)", "Làm rõ (Clarifying)", "Thiết lập chương trình nghị sự (Agenda-Setting)", "Thường quy hóa (Routinizing)"], "q": "Giai đoạn nào diễn ra ngay sau bước \"Ghép nối\" (Matching) trong trình tự mô hình chấp nhận đổi mới (adoption model)?"}, {"a": 2, "o": ["Truy cập có tính phí", "Được tổng hợp ở mức độ cao", "Có thể xử lý được bằng máy tính (Machine-processable)", "Được mã hóa đầu cuối"], "q": "Tiêu chí nào sau đây được liệt kê là điều kiện của dữ liệu mở (open data)?"}], "4": [{"a": 0, "o": ["Bởi vì nhiều cải tiến giá trị bắt nguồn từ chính hoạt động vận hành", "Bởi vì bộ phận vận hành không có khả năng đóng góp vào đổi mới sáng tạo", "Bởi vì sự tách biệt nghiêm ngặt luôn cải thiện đồng thời cả hiệu quả lẫn sáng tạo", "Bởi vì sự sáng tạo chỉ nảy sinh dưới các quy trình ổn định và được kiểm soát chặt chẽ"], "q": "Tại sao việc tách biệt bộ phận R&D khỏi bộ phận vận hành lại không đủ để giải quyết mâu thuẫn giữa tính hiệu quả (efficiency) và tính sáng tạo (creativity)?"}, {"a": 1, "o": ["Tách biệt hoàn toàn hoạt động nghiên cứu khỏi vận hành để tránh xung đột", "Theo đuổi đồng thời cả tính hiệu quả (khai thác) và sự đổi mới sáng tạo (khám phá)", "Chỉ ưu tiên tính hiệu quả và cắt giảm chi phí", "Luân phiên thay đổi giữa khám phá và khai thác theo từng thời kỳ"], "q": "Phát biểu nào mô tả đúng nhất việc thực hiện đồng thời cả khai thác (exploitation) và khám phá (exploration) trong một tổ chức (tổ chức thuận hai tay - ambidextrous organisation)?"}, {"a": 3, "o": ["Thường xuyên có các đổi mới sản phẩm mang tính gián đoạn và triệt để", "Ưu tiên sự thích nghi dài hạn nhanh chóng hơn là tính hiệu quả", "Ít phụ thuộc vào quỹ đạo phát triển cũ (low path-dependency) với sự dịch chuyển công nghệ liên tục", "Chủ yếu là các cải tiến mang tính tiệm tiến (incremental) và tập trung vào quy trình"], "q": "Câu nào mô tả đúng nhất mô thức đổi mới công nghệ điển hình trong các ngành công nghiệp công nghệ thấp (low-technology industries)?"}, {"a": 1, "o": ["Củng cố các năng lực và thói quen vận hành hiện có", "Buộc tổ chức phải phát triển các kỹ năng kỹ thuật và thương mại mới", "Chuyển trọng tâm sang việc chỉ đáp ứng đơn thuần các nhu cầu của khách hàng hiện tại", "Dẫn đến việc các đổi mới tiếp theo ngày càng mang tính tiệm tiến hơn"], "q": "Phát biểu nào mô tả đúng nhất cách thức đổi mới căn bản/triệt để (radical innovation) tác động đến năng lực của một tổ chức đã hoạt động lâu năm?"}, {"a": 1, "o": ["Các thực hành mang tính tự phát, không chính thức và không liên quan đến đổi mới có cấu trúc", "Các quy trình thường nhật thực hiện sự thay đổi bằng cách đổi mới sản phẩm, quy trình và tìm kiếm khách hàng mới", "Các quy trình chỉ cải thiện hiệu quả sản xuất hàng ngày mà không làm thay đổi các lề lối hiện có", "Các quy trình nền tảng nhằm sản xuất và tiếp thị các sản phẩm hiện tại của doanh nghiệp"], "q": "Câu nào mô tả đúng nhất các quy trình thường nhật (routines) giúp thực hiện sự thay đổi thông qua việc đổi mới sản phẩm, quy trình hoặc tìm kiếm khách hàng mới?"}, {"a": 1, "o": ["Đổi mới triệt để (Radical innovation)", "Đổi mới mô-đun (Modular innovation)", "Đổi mới tiệm tiến (Incremental innovation)", "Đổi mới kiến trúc (Architectural innovation)"], "q": "Loại hình đổi mới nào liên quan đến những thay đổi lớn ở các bộ phận cấu thành (components) nhưng ít thay đổi về mối liên kết giữa chúng?"}, {"a": 0, "o": ["Định hướng tăng trưởng (Growth orientation)", "Không gian cho sự sáng tạo (Space for creativity)", "Cam kết về công nghệ và cường độ R&D (Commitment to technology and R&D intensity)", "Chấp nhận rủi ro (Acceptance of risks)"], "q": "Đặc điểm tổ chức nào được định nghĩa là sự cam kết hướng tới tăng trưởng dài hạn thay vì lợi nhuận ngắn hạn?"}, {"a": 2, "o": ["Doanh nghiệp thâm dụng quy mô (Scale-intensive firms)", "Nhà cung cấp thiết bị chuyên dụng (Specialist equipment suppliers)", "Doanh nghiệp phụ thuộc vào nhà cung cấp (Supplier-dominated firms)", "Doanh nghiệp dựa trên khoa học (Science-based firms)"], "q": "Loại hình doanh nghiệp nào thường có rất ít hoạt động R&D nội bộ và chủ yếu mua lại công nghệ từ bên ngoài?"}, {"a": 0, "o": ["Luồng thông tin cởi mở, tự do xuyên suốt toàn bộ tổ chức", "Các quyết định được đưa ra bởi cấp trên với sự tham vấn tối thiểu", "Chuỗi mệnh lệnh dài và các phương pháp làm việc cứng nhắc", "Kiểm soát chặt chẽ thông qua các hệ thống kiểm soát tinh vi"], "q": "Đặc điểm nào sau đây là nét đặc trưng của một cấu trúc tổ chức hữu cơ/linh hoạt (organic organisational structure)?"}, {"a": 2, "o": ["Mối quan hệ thuận: chính thức hóa càng cao thì đổi mới sáng tạo càng tăng", "Sự chính thức hóa chỉ ảnh hưởng đến tính hiệu quả chứ không ảnh hưởng đến đổi mới sáng tạo", "Mối quan hệ nghịch: mức độ chính thức hóa càng cao thường có xu hướng làm giảm tính đổi mới sáng tạo", "Không có mối quan hệ có hệ thống nào giữa sự chính thức hóa và đổi mới sáng tạo"], "q": "Câu nào mô tả đúng nhất mối quan hệ giữa mức độ chính thức hóa các quy trình (formalisation of procedures) và hoạt động đổi mới sáng tạo?"}], "5": [{"a": 2, "o": ["Nó giới hạn hoạt động vận hành chỉ trong các quy trình sản xuất thay vì dịch vụ", "Nó chủ yếu làm giảm lãng phí nguyên vật liệu trong sản xuất", "Nó tạo ra lợi thế cạnh tranh và giúp đạt được các mục tiêu chiến lược", "Nó chỉ liên quan đến việc chuyển giao các kỹ thuật sản xuất sang lĩnh vực dịch vụ"], "q": "Tại sao đổi mới sáng tạo trong chức năng vận hành (operations function) lại quan trọng?"}, {"a": 3, "o": ["Thiết kế, Sản xuất, Tiếp thị, Tài chính", "Đầu vào, Quy trình, Sản phẩm phụ, Đầu ra", "Chiến lược, Kiểm soát chất lượng, Lập lịch trình, Bảo trì", "Chiến lược vận hành, Thiết kế, Hoạch định và kiểm soát, Cải tiến"], "q": "Nhóm nào liệt kê đúng bốn yếu tố chính của chức năng vận hành?"}, {"a": 0, "o": ["Những lợi ích kỳ vọng mà khách hàng đang bỏ tiền ra mua", "Gói các sản phẩm cấu thành mà khách hàng mua", "Thông điệp tiếp thị và hình ảnh thương hiệu của công ty", "Quy trình liên kết các thành phần và dịch vụ để cung cấp sản phẩm/dịch vụ"], "q": "Phát biểu nào định nghĩa đúng nhất khía cạnh \"khái niệm\" (concept) của một sản phẩm hoặc dịch vụ?"}, {"a": 1, "o": ["Tốc độ phục vụ nhanh hơn và hàng đợi ngắn hơn", "Giảm thiểu các vấn đề về giao tiếp và chất lượng", "Gia tăng mức chi tiêu của khách hàng trong mỗi lần ghé thăm", "Giảm nhu cầu đào tạo nhân viên"], "q": "Lợi ích chính của việc đơn giản hóa quy trình dịch vụ bằng cách giảm bớt các khâu chuyển giao thông tin và để khách hàng tham gia trực tiếp là gì?"}, {"a": 1, "o": ["Bởi vì chúng chỉ xảy ra ở các ngành có độ phức tạp thấp", "Bởi vì chúng thường vô hình (không nhìn thấy trực tiếp) đối với người tiêu dùng cuối cùng", "Bởi vì chúng luôn đòi hỏi việc ra quyết định mang tính chiến lược lớn hơn", "Bởi vì chúng hiếm khi làm tăng năng suất của doanh nghiệp"], "q": "Tại sao các đổi mới quy trình (process innovations) thường nhận được ít sự chú ý hơn so với đổi mới sản phẩm (product innovations)?"}, {"a": 0, "o": ["Đổi mới quy trình (Process innovation)", "Đổi mới sản phẩm (Product innovation)", "Đổi mới thiết bị (Equipment innovation)", "Đổi mới nguyên vật liệu thô (Raw-material innovation)"], "q": "Loại hình đổi mới nào có khả năng đạt được sự linh hoạt về sản phẩm (product flexibility) cao nhất trong các ngành công nghiệp chế biến/quy trình (process industries)?"}, {"a": 2, "o": ["Một nhóm công nhân nhỏ do các nhà quản lý lãnh đạo để thực hiện những thay đổi áp đặt", "Một ủy ban quản lý chính thức có nhiệm vụ thực thi các tiêu chuẩn chất lượng", "Một nhóm công nhân tự nguyện quy mô nhỏ họp mặt định kỳ để thảo luận về các vấn đề và đề xuất giải pháp", "Một đội ngũ kiểm toán bên ngoài chuyên chứng nhận sự tuân thủ tiêu chuẩn ISO"], "q": "Phát biểu nào mô tả đúng nhất về một nhóm chất lượng (quality circle)?"}, {"a": 3, "o": ["Kiểm toán tài chính độc lập", "Đối chuẩn (Benchmarking) với các đối thủ cạnh tranh", "Chứng nhận từ bên ngoài", "Tự đánh giá (Self-assessment)"], "q": "Đặc điểm nào của một mô hình kinh doanh xuất sắc (business excellence model) cho thấy cách một tổ chức đánh giá các hoạt động và kết quả của chính mình?"}, {"a": 2, "o": ["Để đảm bảo kiểm soát chất lượng của nhà cung cấp mà không cần điều phối cả mạng lưới", "Để lôi kéo nhà cung cấp tham gia vào thiết kế sản phẩm nhằm giảm chi phí thiết kế", "Để quản lý các hoạt động xuyên suốt ranh giới công ty nhằm làm hài lòng khách hàng", "Để thuê ngoài các hoạt động hỗ trợ nhằm giúp công ty tập trung vào các hoạt động cốt lõi"], "q": "Câu nào mô tả đúng nhất mục tiêu chính của việc điều phối các hoạt động vượt ra ngoài ranh giới công ty (across company boundaries)?"}, {"a": 0, "o": ["Một quy trình phát triển sản phẩm hoặc quy trình mới nhấn mạnh vào việc xác định giá trị và loại bỏ lãng phí khỏi quy trình phát triển sản phẩm mới (NPD)", "Một phương pháp có hệ thống nhằm loại bỏ lãng phí bên trong các quy trình sản xuất", "Một triết lý trì hoãn việc ra mắt cho đến khi sản phẩm đạt đến độ hoàn hảo", "Một chương trình kiểm soát chất lượng từng bước tương tự như Six Sigma"], "q": "Phát biểu nào định nghĩa đúng nhất về đổi mới tinh gọn (lean innovation)?"}], "6": [{"a": 3, "o": ["Nó tự động tạo ra sự bảo hộ quyền tác giả (bản quyền)", "Nó đảm bảo sự độc quyền thương mại vô thời hạn", "Không ai khác có thể khám phá ra ý tưởng đó", "Một người khác có thể độc lập phát minh ra ý tưởng tương tự và đăng ký bảo hộ pháp lý"], "q": "Rủi ro chính của việc chỉ dựa vào việc giữ bí mật (secrecy) để bảo vệ một ý tưởng mới lạ là gì?"}, {"a": 1, "o": ["Nhãn hiệu đã đăng ký (Registered trademarks)", "Bằng sáng chế (Patents)", "Kiểu dáng công nghiệp đã đăng ký (Registered designs)", "Quyền tác giả / Bản quyền (Copyright)"], "q": "Loại hình sở hữu trí tuệ nào mang lại quyền độc quyền trong thời hạn 20 năm?"}, {"a": 1, "o": ["Các nhãn hiệu và biểu trưng (logo) đã đăng ký", "Các phương thức làm việc đặc biệt hoặc chiến lược định giá", "Các thông lệ phổ biến trong ngành và dữ liệu thị trường công khai", "Các bằng sáng chế đã nộp công khai và các nghiên cứu đã xuất bản"], "q": "Yếu tố nào sau đây nhiều khả năng được coi là một bí mật thương mại (trade secret)?"}, {"a": 0, "o": ["Mang tính lừa dối (gây hiểu lầm) và gây nhầm lẫn với các nhãn hiệu đã tồn tại", "Có tính phân biệt và đáp ứng các quy định trình bày theo luật định", "Sử dụng các từ ngữ tán dương hoặc chung chung và được các thương nhân khác sử dụng phổ biến", "Mang tính mô tả và phục vụ một mục đích chức năng"], "q": "Hai đặc điểm nào sẽ khiến đơn đăng ký nhãn hiệu (trademark) bị từ chối?"}, {"a": 2, "o": ["Đảm bảo chất lượng sản phẩm cụ thể", "Chỉ thiết lập quyền sở hữu hợp pháp", "Tạo điều kiện nhận diện danh tính và nguồn gốc xuất xứ", "Xác định chiến lược tiếp thị và các liên tưởng thương hiệu"], "q": "Tên thương hiệu (brand names) và nhãn hiệu (trademarks) có chung chức năng gì?"}, {"a": 1, "o": ["Số tiền chi cho quảng cáo để xây dựng nhận diện thương hiệu", "Tổng giá trị của một thương hiệu với tư cách là một tài sản có thể tách rời", "Quyền đăng ký nhãn hiệu của một doanh nghiệp", "Mức giá cao hơn (price premium) mà một thương hiệu có thể định ra"], "q": "Câu nào sau đây là định nghĩa của \"tài sản thương hiệu\" (brand equity)?"}, {"a": 0, "o": ["Để tiết kiệm chi phí và giảm thiểu rủi ro so với việc tự xây dựng thương hiệu", "Để tránh phải đăng ký và bảo hộ các nhãn hiệu mới", "Để đảm bảo chất lượng sản phẩm cao hơn mà không cần phát triển thêm", "Để thay thế ngay lập tức các sản phẩm của công ty bị mua lại bằng sản phẩm của chính mình"], "q": "Tại sao một doanh nghiệp có thể chọn mua lại một thương hiệu hiện có thay vì tự phát triển một thương hiệu mới?"}, {"a": 2, "o": ["Ý tưởng hoặc khái niệm cốt lõi bên trong", "Nguyên vật liệu được sử dụng hoặc quy trình sản xuất", "Hình dáng bên ngoài: hình khối, cấu hình, hoa văn hoặc đường nét trang trí", "Các tính năng chức năng giúp cải thiện quá trình sử dụng"], "q": "Khía cạnh nào của sản phẩm được bảo hộ thông qua việc đăng ký kiểu dáng công nghiệp (registered design)?"}, {"a": 2, "o": ["Các khoản tiền phạt mang tính trừng phạt để răn đe bên vi phạm", "Một mức phí cố định theo luật định cho mỗi lần vi phạm", "Khoản bồi thường cho những tổn thất thực tế phải gánh chịu", "Lợi nhuận mà bên vi phạm thu được"], "q": "Tiền bồi thường thiệt hại trong một vụ kiện dân sự về quyền tác giả (bản quyền) được tính toán dựa trên cơ sở nào?"}, {"a": 2, "o": ["Việc thực thi pháp luật về sở hữu trí tuệ yếu kém của chính phủ", "Mất bí mật thương mại thông qua sự luân chuyển nhân sự", "Nạn làm giả, sao chép lậu sản phẩm (Product piracy)", "Không đăng ký được nhãn hiệu tại địa phương"], "q": "Yếu tố nào sau đây được xác định là một loại hình xâm phạm quyền sở hữu trí tuệ mà các doanh nghiệp phải đối mặt khi chuyển hoạt động sản xuất ra nước ngoài (offshoring)?"}], "7": [{"a": 0, "o": ["Chúng bị giới hạn bởi vị thế hiện tại và nền tảng tri thức sẵn có của doanh nghiệp", "Bất kỳ doanh nghiệp nào cũng có thể nhanh chóng áp dụng bất kỳ công nghệ mới nào chỉ cần đủ nỗ lực", "Thành công về công nghệ chỉ phụ thuộc vào việc sở hữu công nghệ tiên tiến nhất", "Các cơ hội chỉ phụ thuộc vào nhu cầu thị trường chứ không phụ thuộc vào năng lực của doanh nghiệp"], "q": "Sự phụ thuộc vào quỹ đạo (path dependence) hàm ý điều gì đối với các cơ hội công nghệ của một doanh nghiệp?"}, {"a": 0, "o": ["Khả năng tiếp thu và vận dụng tri thức mới của doanh nghiệp", "Khả năng lưu trữ và quản lý các tập dữ liệu lớn của doanh nghiệp", "Việc doanh nghiệp sở hữu các bằng sáng chế nhằm ngăn chặn sự bắt chước", "Xu hướng đa dạng hóa sang các ngành không liên quan của doanh nghiệp"], "q": "Câu nào định nghĩa đúng nhất về \"năng lực hấp thụ\" (absorptive capacity) của một doanh nghiệp?"}, {"a": 2, "o": ["Sự phụ thuộc quá mức vào các chuyên gia tư vấn bên ngoài để chia sẻ kiến thức", "Tài liệu hóa quá mức gây ra sự chậm trễ trong việc ra quyết định", "Những thông tin giá trị bị thất thoát do sự chia cắt cục bộ giữa các phòng ban (organisational silos)", "Thiếu công nghệ để lưu trữ dữ liệu công ty"], "q": "Vấn đề nào chủ yếu thúc đẩy sự ra đời của quản trị tri thức (knowledge management) trong các tổ chức?"}, {"a": 2, "o": ["Chỉ được ghi chép lại trong các tài liệu và cơ sở dữ liệu", "Tri thức kỹ thuật phổ biến rộng rãi được chia sẻ giữa các doanh nghiệp", "Tri thức đặc thù của doanh nghiệp được tích hợp sâu trong các quy trình thường nhật, hệ thống và các mối quan hệ", "Đơn thuần là phép cộng kiến thức của từng cá nhân nhân viên"], "q": "Phát biểu nào mô tả đúng nhất về tri thức tổ chức mang tính đặc thù riêng của một doanh nghiệp?"}, {"a": 3, "o": ["Chỉ những hoạt động rất gần đây mới ảnh hưởng đến hành động trong tương lai, còn những hoạt động cũ hơn thì không", "Sự học hỏi trong quá khứ chỉ ảnh hưởng đến các chức năng cụ thể (ví dụ: nhân sự hoặc công nghệ) chứ không ảnh hưởng đến toàn bộ hoạt động", "Sự học hỏi của tổ chức trong quá khứ ít hoặc không có ảnh hưởng đến các hoạt động trong tương lai", "Các hoạt động trong tương lai chịu ảnh hưởng mạnh mẽ bởi các hoạt động và sự học hỏi trước đó"], "q": "Phát biểu nào mô tả đúng nhất cách thức các hoạt động và quá trình học hỏi trong quá khứ của một tổ chức ảnh hưởng đến các hoạt động trong tương lai?"}, {"a": 2, "o": ["Giai đoạn thiết kế chủ đạo (Dominant design phase)", "Giai đoạn chuyên biệt (Specific phase)", "Giai đoạn chuyển tiếp (Transitional phase)", "Giai đoạn biến động/linh hoạt (Fluid phase)"], "q": "Giai đoạn nào được đặc trưng bởi sự xuất hiện của một thiết kế chủ đạo (dominant design) và mức độ chấp nhận của thị trường ngày càng tăng?"}, {"a": 1, "o": ["Giảm nhu cầu đầu tư vào các sản phẩm bổ trợ hoặc hệ thống phân phối", "Thu được lợi nhuận độc quyền (monopoly rents) nếu có thể hạn chế được sự bắt chước", "Giảm tầm quan trọng của việc gia tăng năng lực sản xuất", "Đảm bảo sự miễn nhiễm dài hạn trước mọi đối thủ cạnh tranh"], "q": "Lợi ích chính đối với một doanh nghiệp khi sản phẩm của họ trở thành tiêu chuẩn của ngành (industry standard) là gì?"}, {"a": 0, "o": ["Tinh chỉnh và phát triển nhanh chóng các công nghệ hiện có", "Từ bỏ hoàn toàn các năng lực hiện có", "Chỉ tập trung vào việc cắt giảm chi phí cho các sản phẩm hiện tại", "Thuê ngoài toàn bộ hoạt động đổi mới cho các công ty khởi nghiệp bên ngoài"], "q": "Đâu là một trong những nhiệm vụ mà doanh nghiệp phải thực hiện để kết hợp thành công công nghệ hiện có và công nghệ mới?"}, {"a": 3, "o": ["Tối thiểu hóa chi phí sản xuất thông qua tính kinh tế theo quy mô", "Dựa chủ yếu vào việc mua bản quyền (licensing) với công nghệ nội bộ hạn chế", "Nhanh chóng sao chép đối thủ cạnh tranh và thực hiện các cải tiến chi phí thấp", "Ra mắt trước các đối thủ và đầu tư mạnh mẽ vào R&D cũng như tiếp thị (marketing)"], "q": "Đâu là đặc điểm chính của một doanh nghiệp hướng tới mục tiêu giành thế độc quyền công nghệ bằng cách tung sản phẩm mới ra thị trường đầu tiên (chiến lược tấn công - offensive strategy)?"}, {"a": 0, "o": ["Cải tiến sản phẩm của đối thủ trong khi vẫn duy trì sự nhanh nhạy trong sản xuất, thiết kế và tiếp thị", "Ra mắt sản phẩm đầu tiên bằng cách đầu tư lớn vào R&D và tiếp thị rầm rộ", "Cạnh tranh chủ yếu với tư cách là nhà sản xuất chi phí thấp nhờ đạt được tính kinh tế theo quy mô", "Tập trung vào một thị trường ngách hẹp với rất ít thay đổi về sản phẩm"], "q": "Đặc điểm nào tiêu biểu cho chiến lược đổi mới trong đó doanh nghiệp cải tiến sản phẩm của đối thủ cạnh tranh thay vì là người đầu tiên tung ra thị trường (chiến lược phòng thủ - defensive strategy)?"}], "8": [{"a": 0, "o": ["Một thỏa thuận giữa hai hoặc nhiều đối tác nhằm chia sẻ tri thức hoặc nguồn lực vì lợi ích chung", "Sự chuyển giao công nghệ một chiều từ một công ty lớn sang một công ty nhỏ", "Một thỏa thuận hợp đồng giữa các tổ chức nhằm kết hợp nỗ lực và nguồn lực để đạt được một mục tiêu chung", "Sự sáp nhập hoàn toàn hai công ty thành một pháp nhân duy nhất"], "q": "Lựa chọn nào định nghĩa đúng nhất về một liên minh chiến lược (strategic alliance)?"}, {"a": 0, "o": ["Doanh nghiệp lớn tiếp cận được chuyên môn kỹ thuật của doanh nghiệp nhỏ; doanh nghiệp nhỏ có được nguồn vốn và thị trường", "Chúng loại bỏ nhu cầu đầu tư vào R&D của các doanh nghiệp", "Chúng tạo ra một doanh nghiệp hợp nhất duy nhất thông qua sáp nhập", "Chúng đảm bảo quyền kiểm soát đối với công nghệ của đối tác"], "q": "Liên minh chiến lược mang lại lợi ích gì cho cả doanh nghiệp lớn và doanh nghiệp nhỏ?"}, {"a": 2, "o": ["Mong muốn duy trì bí mật cạnh tranh", "Các hạn chế pháp lý về việc chia sẻ thông tin", "Sự thiếu tin tưởng lẫn nhau (Lack of trust)", "Chi phí nghiên cứu và phát triển cao"], "q": "Lý do chính khiến các doanh nghiệp ngần ngại chia sẻ ý tưởng và công nghệ với các công ty khác là gì?"}, {"a": 2, "o": ["Để giải quyết thế tiến thoái lưỡng nan của người tù (prisoner's dilemma) giữa các công ty", "Để thuê ngoài hoạt động sản xuất thông thường nhằm cắt giảm chi phí sản xuất", "Để chia sẻ chi phí và rủi ro R&D ngày càng tăng nhằm giúp doanh nghiệp duy trì khả năng cạnh tranh", "Để loại bỏ vĩnh viễn đối thủ cạnh tranh thông qua việc thâu tóm"], "q": "Tại sao các mối quan hệ đối tác công nghệ ngày càng trở nên quan trọng đối với các doanh nghiệp?"}, {"a": 3, "o": ["Cạnh tranh chỉ gói gọn trong thị trường nội địa", "Gia tăng tính độc lập của từng doanh nghiệp riêng lẻ", "Giảm nhu cầu đối với các tài sản bổ trợ", "Quyền lực chiến lược nằm trong tay các nhóm doanh nghiệp hợp tác với nhau"], "q": "Kết quả nào phản ánh đúng nhất việc các doanh nghiệp lựa chọn tham gia liên minh chiến lược thay vì tự mình đơn độc thực hiện (go-it-alone approach)?"}, {"a": 3, "o": ["Chỉ mang lại lợi ích cho các doanh nghiệp lớn đã có tên tuổi", "Suy giảm đổi mới sáng tạo do bị đánh cắp thông tin", "Không có tác động đo lường được đối với đổi mới sáng tạo", "Cải thiện hiệu quả hoạt động đổi mới sáng tạo cho các doanh nghiệp nhỏ và vừa (SMEs)"], "q": "Kết quả nào gắn liền nhất với sự hợp tác liên doanh nghiệp giữa các doanh nghiệp nhỏ và vừa (SMEs)?"}, {"a": 3, "o": ["Bởi vì chỉ riêng bằng sáng chế và cấp phép là đủ để chuyển giao công nghệ", "Để dựa vào thương hiệu toàn cầu và hệ thống phân phối thay vì công nghệ mới", "Để tránh nhu cầu phải liên tục đổi mới sản phẩm và công nghệ", "Để có được công nghệ đi kèm với các kỹ năng, bí quyết ngầm (tacit know-how) và năng lực chuyên môn"], "q": "Tại sao các doanh nghiệp lâu đời lại thiết lập liên minh để tiếp cận các công nghệ mới?"}, {"a": 0, "o": ["Biệt phái nhân sự và trao đổi nhân viên (Staff secondment and employee exchanges)", "Chuyển giao dữ liệu điện tử của các tài liệu", "Các thỏa thuận cấp phép bằng sáng chế", "Các chiến dịch quảng cáo công khai và xây dựng thương hiệu"], "q": "Hoạt động nào tạo điều kiện trực tiếp nhất cho việc chuyển giao tri thức ngầm (tacit knowledge) giữa các doanh nghiệp đối tác?"}, {"a": 2, "o": ["Thỏa thuận trao đổi hàng hóa (Barter agreements)", "Nhượng quyền thương mại (Franchising)", "Liên doanh (Joint venture)", "Sáp nhập (Mergers)"], "q": "Hình thức nào sau đây là một trong tám loại hình liên minh chiến lược cơ bản?"}, {"a": 2, "o": ["Một thỏa thuận cấp phép trong đó một công ty cấp phép công nghệ của mình cho nhiều công ty khác", "Một liên doanh góp vốn chính thức được thành lập như một pháp nhân độc lập", "Một thợ điện hành nghề cá thể thiết lập mối quan hệ lâu dài với nhà cung cấp để nhận được chiết khấu và các dịch vụ đặc biệt", "Một công ty ảo thuê ngoài mọi chức năng kinh doanh cho các nhà cung cấp bên ngoài"], "q": "Ví dụ nào minh họa rõ nhất cho một mối quan hệ nhà cung cấp đơn giản (simple supplier relationship)?"}], "9": [{"a": 1, "o": ["Nghiên cứu ứng dụng $\\rightarrow$ Nghiên cứu cơ bản $\\rightarrow$ Phát triển $\\rightarrow$ Dịch vụ kỹ thuật", "Nghiên cứu cơ bản (Basic research) $\\rightarrow$ Nghiên cứu ứng dụng (Applied research) $\\rightarrow$ Phát triển (Development) $\\rightarrow$ Dịch vụ kỹ thuật (Technical service)", "Dịch vụ kỹ thuật $\\rightarrow$ Phát triển $\\rightarrow$ Nghiên cứu ứng dụng $\\rightarrow$ Nghiên cứu cơ bản", "Nghiên cứu cơ bản $\\rightarrow$ Phát triển $\\rightarrow$ Nghiên cứu ứng dụng $\\rightarrow$ Dịch vụ kỹ thuật"], "q": "Trình tự nào sắp xếp đúng các giai đoạn từ tri thức khoa học cho đến khi tạo ra sản phẩm vật chất?"}, {"a": 1, "o": ["Một bảng phân loại được sử dụng để mô tả các sản phẩm và quy trình", "Việc ứng dụng tri thức để đạt được một kết quả thực tiễn", "Phương pháp tiếp cận có hệ thống để khám phá ra tri thức mới", "Nền tảng tri thức của một công ty bao gồm cả năng lực R&D của công ty đó"], "q": "Cụm từ nào định nghĩa đúng nhất về \"công nghệ\" (technology)?"}, {"a": 1, "o": ["Tránh quản lý chính thức và chỉ dựa vào sự may rủi cùng việc tự do khám phá", "Điều chỉnh hoạt động quản trị R&D cho phù hợp với truyền thống lịch sử, nguồn lực và bối cảnh ngành của doanh nghiệp", "Áp dụng một mô hình quản trị R&D tiêu chuẩn hóa duy nhất cho tất cả các doanh nghiệp", "Chỉ quản lý R&D bằng cách cố định mức chi tiêu R&D theo tỷ lệ phần trăm doanh thu"], "q": "Câu nào mô tả đúng nhất cách thức một doanh nghiệp nên quản trị hoạt động R&D của mình?"}, {"a": 3, "o": ["Chỉ các doanh nghiệp nhỏ mới có thể quản lý R&D tốt hơn các doanh nghiệp lớn", "Thành công của R&D chủ yếu phụ thuộc vào sự may mắn hơn là quản trị", "Hoạt động này về bản chất là không thể quản lý được vì nghiên cứu có quá nhiều bất định", "Hoạt động này hoàn toàn có thể quản trị được, và nhiều doanh nghiệp lớn đã vận hành R&D rất thành công"], "q": "Phát biểu nào mô tả đúng nhất về khả năng quản trị hoạt động nghiên cứu công nghệ trong công nghiệp?"}, {"a": 2, "o": ["Để đo lường khả năng sinh lời của từng dự án R&D riêng lẻ", "Để cho biết số tiền tuyệt đối mà các doanh nghiệp chi cho R&D giữa các ngành", "Để cho phép so sánh công bằng giữa các doanh nghiệp có quy mô khác nhau và thể hiện cường độ R&D (R&D intensity)", "Để chuẩn hóa các phương pháp kế toán R&D giữa các quốc gia"], "q": "Tại sao chi phí R&D thường được biểu thị dưới dạng tỷ lệ phần trăm trên doanh thu?"}, {"a": 3, "o": ["Chủ yếu là các kỹ thuật quản lý nghiêm ngặt, chính thức", "Phần lớn là việc tuyển dụng các thiên tài công nghệ đơn độc", "Chủ yếu là sự tình cờ (serendipity) và may rủi", "Sự kết hợp giữa yếu tố tình cờ/khám phá ngẫu nhiên (serendipity) và các kỹ thuật quản trị chính thức"], "q": "Phát biểu nào mô tả đúng nhất bản chất của quản trị R&D?"}, {"a": 1, "o": ["Một động lực thúc đẩy lợi nhuận ngắn hạn mà doanh nghiệp nên ưu tiên hơn các khoản đầu tư khác", "Một khoản đầu tư dài hạn có thể làm giảm lợi nhuận ngắn hạn và là cơ sở biện minh cho việc nhà nước tài trợ cho nghiên cứu thuần túy (pure research)", "Trách nhiệm thuộc về riêng chính phủ mà không có vai trò của khối doanh nghiệp", "Một hoạt động không tốn kém và chủ yếu do khu vực tư nhân tài trợ với lợi tức thu về ngay lập tức"], "q": "Câu nào mô tả đúng nhất quan điểm kinh tế về đầu tư cho R&D?"}, {"a": 3, "o": ["Các tổ chức phi lợi nhuận", "Các cá nhân nộp thuế", "Các tập đoàn đa quốc gia lớn", "Các doanh nghiệp nhỏ và doanh nghiệp khởi nghiệp (start-up)"], "q": "Đối tượng doanh nghiệp nào đặc biệt là đối tượng thụ hưởng mục tiêu của các chính sách ưu đãi thuế cho R&D của chính phủ?"}, {"a": 0, "o": ["Ngày càng được định hướng bởi chiến lược kinh doanh của công ty và các nhà đầu tư tài chính", "Theo đuổi tri thức mới được tài trợ bởi ngân sách công vì lợi ích chung của xã hội", "Chỉ tập trung cải tiến quy trình sản xuất để cắt giảm chi phí", "Xuất bản các bài báo khoa học và chia sẻ miễn phí các khám phá"], "q": "Theo thời gian, các ưu tiên định hướng hoạt động R&D trong công nghiệp đã thay đổi như thế nào?"}, {"a": 2, "o": ["Duy trì sự kiểm soát chặt chẽ, hiệu quả nhưng lại hạn chế sự đổi mới sáng tạo", "Cắt giảm hoạt động R&D nội bộ bằng cách thuê ngoài để giảm chi phí", "Nuôi dưỡng sự sáng tạo và tìm tòi khám phá trong khi vẫn duy trì sự quản trị ổn định và hiệu quả", "Ưu tiên sự sáng tạo mà đánh đổi sự ổn định trong quản trị"], "q": "Phát biểu nào mô tả đúng nhất tình thế tiến thoái lưỡng nan cốt lõi về quản trị mà các tổ chức phải đối mặt?"}], "10": [{"a": 1, "o": ["Bởi vì các doanh nghiệp đa công nghệ có thể dễ dàng dẫn đầu trong mọi lĩnh vực công nghệ", "Bởi vì việc tự phát triển nội bộ thường quá nhiều bất định, tốn kém và chậm chạp", "Bởi vì chính phủ yêu cầu các doanh nghiệp phải mua công nghệ từ bên ngoài", "Bởi vì tri thức và công nghệ không còn là những tài sản kinh doanh chủ chốt nữa"], "q": "Tại sao ngày càng có nhiều tổ chức tìm kiếm các nguồn công nghệ từ bên ngoài?"}, {"a": 1, "o": ["Bảo vệ tài sản trí tuệ để đối thủ cạnh tranh không thể sử dụng công nghệ", "Hợp tác với những nhân tài ở các doanh nghiệp khác", "Chỉ dựa hoàn toàn vào đội ngũ nhân tài nội bộ", "Tự thực hiện toàn bộ hoạt động R&D trong nội bộ để thu trọn lợi nhuận"], "q": "Phát biểu nào minh họa rõ nhất một nguyên tắc của đổi mới sáng tạo mở (open innovation)?"}, {"a": 3, "o": ["Sự cởi mở chỉ cần thiết trong giai đoạn nghiên cứu, còn sự bảo hộ chỉ cần khi ra mắt sản phẩm", "Doanh nghiệp buộc phải lựa chọn hoặc là hợp tác, hoặc là bảo hộ", "Sự hợp tác luôn đảm bảo thương mại hóa thành công bất kể cơ chế quản trị ra sao", "Việc tạo ra các đổi mới sáng tạo thường đòi hỏi sự cởi mở, trong khi việc thương mại hóa chúng lại đòi hỏi sự bảo hộ"], "q": "Phát biểu nào tóm tắt chính xác nhất sự giằng co mà các doanh nghiệp phải đối mặt khi hợp tác để đổi mới sáng tạo?"}, {"a": 1, "o": ["Các hợp đồng R&D bên ngoài phù hợp khi doanh nghiệp chưa có kiến thức nền tảng gì về công nghệ đó", "Việc mua công nghệ bên ngoài thường cần ít kiến thức nền tảng; trong khi việc ký hợp đồng R&D bên ngoài hoặc lập liên minh đòi hỏi kiến thức nền tảng cao", "Việc mua công nghệ bên ngoài luôn đòi hỏi sự kiểm soát kỹ thuật nhiều hơn so với ký hợp đồng R&D bên ngoài", "Cả việc mua công nghệ và ký hợp đồng R&D bên ngoài đều đòi hỏi mức độ kiến thức nền tảng như nhau"], "q": "Kiến thức nền tảng sẵn có (prior knowledge) ảnh hưởng như thế nào đến việc lựa chọn giữa mua công nghệ bên ngoài và ký hợp đồng thuê R&D bên ngoài?"}, {"a": 2, "o": ["Quét/rò tìm công nghệ (Technology scanning)", "Mua đứt công nghệ (Purchase of technology)", "Tự nghiên cứu và phát triển nội bộ (Internal R&D)", "Các công ty liên doanh (Joint ventures)"], "q": "Phương thức tiếp nhận/phát triển công nghệ nào đòi hỏi mức độ hội nhập tổ chức (organisational integration) cao nhất?"}, {"a": 3, "o": ["Đối thủ cạnh tranh luôn bị cấm nhận cấp phép công nghệ đó", "Việc cấp phép không liên quan đến bằng sáng chế hay sở hữu trí tuệ", "Bên nhận cấp phép luôn nhận được sự hỗ trợ phát triển toàn diện", "Chủ sở hữu nhận được phí cấp phép (licence fee) để cho phép quyền tiếp cận và sử dụng công nghệ"], "q": "Đâu là đặc điểm cơ bản của một thỏa thuận cấp phép bản quyền (licensing arrangement)?"}, {"a": 1, "o": ["Chỉ chuyển giao các quy trình và tài liệu bằng văn bản thay vì tri thức ngầm", "Tuyển dụng nhân sự giàu kinh nghiệm từ các công ty khác hoặc trường đại học – những người mang theo kỹ năng và phương pháp làm việc có thể áp dụng được ngay", "Bán giấy phép cho phép các công ty khác sử dụng các công nghệ đã được cấp bằng sáng chế", "Đảm bảo rằng mọi thông lệ từ nơi làm việc cũ đều có thể được sao chép nguyên bản sang tổ chức mới"], "q": "Câu nào mô tả đúng nhất cách thức việc tuyển dụng nhân sự có kỹ năng tạo điều kiện cho chuyển giao công nghệ?"}, {"a": 3, "o": ["Các cố vấn tập trung vào quản lý nhưng có rất ít kinh nghiệm kỹ thuật", "Các nhà cung cấp chính về bằng sáng chế và quyền cấp phép", "Người thay thế cho toàn bộ bộ phận R&D của một tổ chức", "Các cựu nhân viên nghiên cứu có khả năng cung cấp chuyên môn kỹ thuật chuyên sâu"], "q": "Câu nào mô tả đúng nhất nền tảng điển hình của các chuyên gia tư vấn công nghệ (technology consultants) được sử dụng trong chuyển giao công nghệ?"}, {"a": 2, "o": ["Một vật thể hữu hình được mua từ nhà cung cấp bên ngoài", "Một gói tài liệu kỹ thuật đơn thuần", "Sự kết hợp giữa tri thức, kỹ năng và cách thức tổ chức", "Một bên trung gian bên ngoài cung cấp quyền tiếp cận công nghệ"], "q": "Phát biểu nào mô tả đúng nhất về \"bí quyết tổ chức\" (organisational know-how) trong quá trình chuyển giao công nghệ từ bên ngoài vào (inward technology transfer)?"}, {"a": 2, "o": ["Nhận thức (Awareness), Liên kết (Association), Ứng dụng (Application), Đồng hóa (Assimilation)", "Liên kết, Nhận thức, Đồng hóa, Ứng dụng", "Nhận thức (Awareness), Liên kết (Association), Đồng hóa (Assimilation), Ứng dụng (Application)", "Nhận thức, Đồng hóa, Liên kết, Ứng dụng"], "q": "Lựa chọn nào liệt kê đúng thứ tự các giai đoạn mà một tổ chức thực hiện để đưa công nghệ bên ngoài vào sử dụng trong nội bộ (Mô hình 4A)?"}], "11": [{"a": 1, "o": ["Thể hiện cấu trúc nội bộ, các vai trò và tuyến báo cáo của công ty", "Mô tả giá trị được cung cấp và cách thức doanh nghiệp tạo ra, chuyển giao và thu về doanh thu (nắm bắt giá trị)", "Liệt kê các tính năng sản phẩm, thông số kỹ thuật và chi tiết thiết kế", "Chỉ xác định thị trường mục tiêu và các phân khúc khách hàng"], "q": "Phát biểu nào mô tả đúng nhất mục đích của một mô hình kinh doanh (business model)?"}, {"a": 3, "o": ["Các phương pháp kế toán thuế", "Lý lịch cá nhân của Giám đốc điều hành (CEO)", "Thiết kế biểu trưng (logo) của công ty", "Khách hàng mục tiêu (Target customer)"], "q": "Yếu tố nào sau đây là một câu hỏi cốt lõi mà một mô hình kinh doanh phải giải quyết?"}, {"a": 0, "o": ["Sự mô tả về vấn đề của khách hàng, sản phẩm giải quyết vấn đề đó, và giá trị mang lại dưới góc nhìn của khách hàng", "Cách thức tạo ra doanh thu, cơ cấu chi phí và biên lợi nhuận mục tiêu", "Vị thế và các hoạt động của doanh nghiệp trong chuỗi giá trị cũng như cách doanh nghiệp chiếm lĩnh một phần giá trị đó", "Việc xác định nhóm khách hàng để nhắm mục tiêu"], "q": "Lựa chọn nào định nghĩa đúng nhất về \"tuyên ngôn giá trị\" (value proposition) của một doanh nghiệp?"}, {"a": 2, "o": ["Để giảm chi phí phát triển sản phẩm ban đầu", "Để đảm bảo khả năng sinh lời ngay lập tức", "Để tạo điều kiện cho tiềm năng tăng trưởng theo cấp số nhân", "Để đạt được biên lợi nhuận cao hơn"], "q": "Tại sao các nhà đầu tư thường tìm kiếm một mô hình kinh doanh có khả năng mở rộng quy mô (scalable business model) ở một công ty khởi nghiệp (start-up)?"}, {"a": 2, "o": ["Chỉ nhấn mạnh vào các dòng doanh thu và biên lợi nhuận", "Bỏ qua các bên liên quan bên ngoài và các yếu tố pháp lý", "Các hệ thống phân loại quy trình mang tính trừu tượng không đồng nhất với cấu trúc và hệ thống thực tế của doanh nghiệp", "Sự phụ thuộc vào Chuỗi giá trị của Porter (Porter's Value Chain)"], "q": "Câu nào mô tả một hạn chế chính của nhiều khung mô hình kinh doanh (business-model frameworks)?"}, {"a": 1, "o": ["Bảng phân công nhân sự chi tiết đến từng phút", "Một tập hợp các chỉ số hoặc thước đo để đo lường sự liên kết giữa các hoạt động", "Các dự báo tài chính chi tiết dài từ 50 đến 100 trang", "Các hợp đồng có tính ràng buộc pháp lý với nhà cung cấp"], "q": "Một mô hình kinh doanh nên bao gồm yếu tố nào sau đây để đánh giá các mối liên kết giữa các hoạt động?"}, {"a": 2, "o": ["Doanh nhân khởi nghiệp (Entrepreneur / serial entrepreneur)", "Nhà phát minh / người sáng tạo (Inventor/creator)", "Nhà sản xuất (Manufacturer)", "Chủ sở hữu tài sản trí tuệ cho thuê (Intellectual landlord)"], "q": "Hình mẫu mô hình kinh doanh (business model archetype) nào tập trung vào việc sản xuất hàng hóa vật chất bằng cách lắp ráp/kết hợp các tài sản vật chất?"}, {"a": 1, "o": ["Chỉ dựa vào các tài sản và năng lực hiện có", "Thách thức các giả định mặc định của ngành và những tư duy lối mòn thông thường", "Giảm giá bán và cắt giảm chi phí vận hành", "Sao chép các thông lệ hiện tại của đối thủ cạnh tranh"], "q": "Hành động nào đóng vai trò trung tâm nhất trong việc tái định nghĩa mô hình kinh doanh của một doanh nghiệp?"}, {"a": 1, "o": ["Năng lực cốt lõi và mạng lưới đối tác", "Các nỗ lực tạo ra doanh thu và cơ cấu chi phí", "Tuyên ngôn giá trị và các kênh phân phối", "Quan hệ khách hàng và các dòng doanh thu"], "q": "Hai phần nào cấu thành nên bản mô tả gồm hai phần của mô hình kinh doanh về cách thức vận hành của một công ty khởi nghiệp?"}, {"a": 0, "o": ["Loại giá trị hoặc lợi ích nào, và mức độ bao nhiêu, gắn liền với sản phẩm/dịch vụ được cung cấp", "Hồ sơ nhân khẩu học của khách hàng mục tiêu", "Các điều khoản hợp đồng của đối tác chuỗi cung ứng", "Biên lợi nhuận dự kiến của công ty"], "q": "Yếu tố nào sau đây là thành phần chính của một tuyên ngôn giá trị (value proposition statement)?"}], "12": [{"a": 2, "o": ["Tung ra các sản phẩm rất giống với các sản phẩm hiện có để giảm thiểu rủi ro", "Chỉ tập trung vào năng lực kỹ thuật của doanh nghiệp", "Đánh giá năng lực công nghệ và nhu cầu thị trường trong tương lai để hình dung ra các sản phẩm/dịch vụ cho khách hàng", "Sử dụng dữ liệu tìm kiếm trên internet để dự báo doanh số ngắn hạn"], "q": "Hoạt động nào nắm bắt đúng nhất ý nghĩa của \"tầm nhìn thị trường\" (market vision)?"}, {"a": 1, "o": ["Các lượt tìm kiếm chỉ rõ tên công nghệ", "Các lượt tìm kiếm chỉ rõ tên thương hiệu của sản phẩm", "Các lượt tìm kiếm chỉ rõ danh mục sản phẩm chung", "Các thước đo chỉ số vĩ mô (ví dụ: tăng trưởng GDP, giá dầu)"], "q": "Tín hiệu nào được phát hiện là giúp dự báo doanh số bán ô tô tốt hơn?"}, {"a": 2, "o": ["Chủ yếu dựa vào nghiên cứu khoa học thay vì trải nghiệm người dùng", "Là các công ty cung cấp thiết bị và linh kiện cho nhà sản xuất", "Dự đoán trước các nhu cầu quan trọng của thị trường và tự phát triển các đổi mới sáng tạo của riêng họ", "Chỉ chấp nhận sản phẩm sau khi thị trường đã chấp nhận rộng rãi"], "q": "Đâu là đặc điểm của nhóm người dùng tiên phong (lead users)?"}, {"a": 1, "o": ["Thuê ngoài hoạt động sản xuất sản phẩm cho các nhà thầu bên ngoài", "Một phương pháp thu thập ý tưởng, nội dung, sự hỗ trợ hoặc giải pháp từ một nhóm đông đảo công chúng/cộng đồng", "Một chương trình đề xuất sáng kiến nội bộ chỉ dành cho nhân viên nhằm cắt giảm chi phí", "Một phần mềm tự động tạo ra ý tưởng cho các nhà quản lý"], "q": "Phát biểu nào định nghĩa đúng nhất về \"huy động nguồn lực cộng đồng\" (crowdsourcing)?"}, {"a": 2, "o": ["Đưa ra phần thưởng tài chính cho tất cả những người tham gia", "Giới hạn sự tham gia chỉ trong phạm vi nhân viên công ty", "Nêu rõ ràng chính xác ý tưởng hoặc giải pháp nào đang được yêu cầu", "Chỉ đưa ra các mục tiêu chung chung mà không có yêu cầu cụ thể"], "q": "Phát biểu nào mô tả đúng nhất về một \"phạm vi được xác định rõ ràng\" (well-defined scope) trong crowdsourcing?"}, {"a": 1, "o": ["Những người lớn tuổi hơn, giàu có hơn và có trình độ học vấn cao hơn", "Những người trẻ tuổi hơn, giàu có hơn và có trình độ học vấn cao hơn", "Những người trung niên, có thu nhập trung bình và trình độ học vấn trung bình", "Những người trẻ tuổi hơn, có thu nhập thấp hơn và trình độ học vấn thấp hơn"], "q": "Đặc điểm nhân khẩu học nào tiêu biểu cho nhóm người tiên phong (innovators) và nhóm người chấp nhận sớm (early adopters)?"}, {"a": 0, "o": ["Vì chúng đòi hỏi những thay đổi đáng kể trong tư duy và hành vi của người tiêu dùng", "Vì chúng chỉ liên quan đến những điều chỉnh nhỏ về mặt nhận thức", "Vì chúng chủ yếu bị từ chối do người tiêu dùng không thích công nghệ mới", "Vì chúng lan tỏa dễ dàng mà người tiêu dùng không cần nhận thấy lợi ích"], "q": "Tại sao các đổi mới gián đoạn/phi liên tục (discontinuous innovations) thường khó được người tiêu dùng chấp nhận hơn?"}, {"a": 2, "o": ["Rủi ro cảm nhận và chi phí cảm nhận", "Tính tương thích cảm nhận và tính phức tạp cảm nhận", "Tính hữu ích cảm nhận (Perceived usefulness) và tính dễ sử dụng cảm nhận (perceived ease of use)", "Sự thích thú cảm nhận và ảnh hưởng xã hội"], "q": "Cặp nhận thức nào đóng vai trò trung tâm trong việc giải thích sự chấp nhận của người dùng đối với một hệ thống công nghệ (Mô hình TAM)?"}, {"a": 3, "o": ["Chi phí sản xuất thấp", "Chi tiêu quảng cáo cao", "Quy định pháp lý nghiêm ngặt", "Sự thiếu quen thuộc (Lack of familiarity)"], "q": "Yếu tố nào được đề cập là có ảnh hưởng đến sự đánh giá của người tiêu dùng đối với các đổi mới gián đoạn?"}, {"a": 1, "o": ["Chấp nhận: bắt nguồn từ xã hội học và tập trung vào xã hội; Lan tỏa: dựa trên tâm lý học cá nhân", "Chấp nhận: quá trình của từng cá nhân từ lúc nhận biết đến khi ra quyết định; Lan tỏa: quá trình truyền thông/phổ biến theo thời gian trong một hệ thống xã hội", "Chấp nhận: sự truyền thông theo thời gian trong một hệ thống xã hội; Lan tỏa: quá trình ra quyết định của cá nhân", "Chấp nhận: sự tăng trưởng thị phần sản phẩm; Lan tỏa: những thay đổi kỹ thuật của sản phẩm"], "q": "Câu nào phân biệt đúng nhất giữa \"sự chấp nhận\" (adoption) và \"sự lan tỏa\" (diffusion)?"}], "13": [{"a": 1, "o": ["Quản trị sản xuất", "Tiếp thị (Marketing)", "Kinh tế học", "Thiết kế và kỹ thuật"], "q": "Lĩnh vực chuyên môn nào trong phát triển sản phẩm mới (NPD) tập trung chủ yếu vào việc thấu hiểu nhu cầu khách hàng?"}, {"a": 2, "o": ["Thiết kế các linh kiện đặc thù cho sản phẩm", "Phát triển và cung ứng thiết bị quy trình sản xuất", "Các giá trị mục tiêu của những thuộc tính sản phẩm (Target values of product attributes)", "Cấu hình của chuỗi cung ứng vật chất"], "q": "Yếu tố nào sau đây là một trong năm quyết định cơ bản trong giai đoạn phát triển khái niệm sản phẩm (concept development)?"}, {"a": 2, "o": ["Các giám đốc tiếp thị (Marketing managers)", "Chủ sở hữu doanh nghiệp", "Các nhà hoạch định chiến lược và các nhà quản lý cấp cao", "Các đội ngũ R&D"], "q": "Ai thường là người dẫn dắt hoạt động hoạch định chiến lược cấp công ty (corporate planning) trong các tổ chức lớn?"}, {"a": 1, "o": ["Rút lui khỏi thị trường để tập trung vào các sản phẩm khác", "Khởi động một số dự án phát triển sản phẩm có mục tiêu cụ thể", "Chỉ thay đổi hoạt động truyền thông tiếp thị", "Tung ra một chương trình phát triển hợp nhất duy nhất"], "q": "Kết quả tức thì nào có khả năng xảy ra khi các nhà hoạch định thị trường biết được đối thủ cạnh tranh sắp giới thiệu một sản phẩm cải tiến?"}, {"a": 0, "o": ["Bởi vì sự nhận thức cao về công nghệ và việc quét/theo dõi liên tục sẽ tạo ra các cơ hội kỹ thuật", "Bởi vì nó loại bỏ nhu cầu phải thực hiện R&D", "Bởi vì nó trực tiếp và luôn luôn làm giảm chi phí phát triển sản phẩm", "Bởi vì xu hướng thị trường thay đổi nhanh hơn sự phát triển công nghệ"], "q": "Tại sao việc quản trị công nghệ lại đặc biệt quan trọng trong các ngành thâm dụng khoa học và công nghệ?"}, {"a": 3, "o": ["Có nghĩa là các quy trình có thể dự đoán và lặp lại được cho đổi mới sáng tạo", "Chỉ đề cập đến nghiên cứu thị trường và phân tích đối thủ cạnh tranh", "Đại diện cho các đầu vào được lên kế hoạch từ hoạt động hoạch định chính thức của công ty", "Cung cấp các đầu vào đa dạng, không nằm trong kế hoạch nhưng có thể dẫn đến những cơ hội mới"], "q": "Yếu tố tình cờ/may mắn bất ngờ (serendipity) đóng vai trò gì trong việc nhận diện các cơ hội sản phẩm?"}, {"a": 1, "o": ["Mua lại một công ty văn phòng phẩm", "Quảng bá một loại ngũ cốc hiện có như một món ăn vặt (snack)", "Xuất khẩu loại ngũ cốc đó sang một quốc gia mới", "Giới thiệu một hương vị ngũ cốc mới"], "q": "Hoạt động nào minh họa rõ nhất cho việc gia tăng doanh số bán hàng trong các thị trường hiện tại đối với một sản phẩm hiện có (chiến lược thâm nhập thị trường)?"}, {"a": 3, "o": ["Tăng doanh số của các sản phẩm hiện tại trong các thị trường hiện có", "Phát triển các sản phẩm mới hoặc cải tiến cho khách hàng hiện tại", "Giới thiệu các sản phẩm mới vào những thị trường mà doanh nghiệp chưa hiện diện", "Bán các sản phẩm hiện tại cho các phân khúc khách hàng mới hoặc các khu vực địa lý mới"], "q": "Lựa chọn nào mô tả một chiến lược sử dụng các sản phẩm hiện tại để thâm nhập vào các phân khúc khách hàng mới hoặc khu vực địa lý mới (chiến lược phát triển thị trường)?"}, {"a": 0, "o": ["Các sản phẩm mới đối với toàn thế giới (New-to-the-world products)", "Các dòng sản phẩm mới đối với công ty (New product lines)", "Các dự án cắt giảm chi phí (Cost reductions)", "Các cải tiến sản phẩm (Product improvements)"], "q": "Danh mục dự án sản phẩm mới nào mang lại rủi ro cao nhất cho các doanh nghiệp?"}, {"a": 1, "o": ["Các mô hình dựa trên nền tảng (Platform-based models)", "Các mô hình giai đoạn quyết định (Decision-stage models)", "Các mô hình Agile-scrum (Agile-scrum models)", "Các mô hình khởi nghiệp tinh gọn (Lean startup models)"], "q": "Mô hình nào sau đây là một trong tám nhóm được sử dụng để phân loại các mô hình phát triển sản phẩm mới?"}], "14": [{"a": 3, "o": ["Gây ra các lỗi kỹ thuật trong sản xuất", "Giảm thời gian và chi phí phát triển", "Đánh mất khả năng dẫn dắt sở thích của khách hàng", "Tung ra thị trường những sản phẩm mà khách hàng không mong muốn"], "q": "Rủi ro chính mà các doanh nghiệp phải đối mặt nếu không tiến hành nghiên cứu thị trường đầy đủ là gì?"}, {"a": 0, "o": ["Mang tính lặp đi lặp lại (iterative) và gắn kết chặt chẽ với nhau thông qua các vòng phản hồi", "Là các bước tuần tự nghiêm ngặt với ranh giới rõ ràng", "Là các hoạt động chỉ diễn ra sau khi sản phẩm đã ra mắt thị trường", "Là các hoạt động độc lập chỉ được thúc đẩy bởi các thông số kỹ thuật"], "q": "Câu nào mô tả đúng nhất mối quan hệ giữa thử nghiệm khái niệm (concept testing), phát triển mẫu thử (prototype development) và thử nghiệm sản phẩm (product testing) trong phát triển sản phẩm mới?"}, {"a": 3, "o": ["Bởi vì người tiêu dùng cố tình khai báo sai sở thích trong quá trình nghiên cứu", "Bởi vì nghiên cứu thị trường bị pháp luật cấm ở nhiều thị trường", "Bởi vì nghiên cứu thị trường luôn bộc lộ mọi nhu cầu tiềm ẩn của người tiêu dùng", "Bởi vì người tiêu dùng thường không thể diễn đạt rõ các nhu cầu tiềm năng của họ, do đó nghiên cứu thị trường sẽ bỏ lỡ các cơ hội mới lạ"], "q": "Tại sao một số doanh nghiệp chọn cách dẫn dắt thị trường thay vì dựa vào nghiên cứu thị trường?"}, {"a": 0, "o": ["Ước tính phản ứng có thể xảy ra của thị trường trước khi tốn kém chi phí sản xuất và xúc tiến thương mại", "Đảm bảo sự phê duyệt của cơ quan quản lý để bán sản phẩm", "Hoàn thiện các chi tiết về bao bì và nhãn mác", "Tính toán chính xác chi phí sản xuất trên mỗi đơn vị sản phẩm"], "q": "Mục tiêu chính của việc thử nghiệm một sản phẩm mới đề xuất trước khi đưa vào sản xuất là gì?"}, {"a": 3, "o": ["Nó chỉ hữu ích cho việc định giá sản phẩm", "Nó đo lường sự chấp nhận dài hạn tốt hơn phản ứng ban đầu", "Nó luôn dự đoán chính xác sở thích của người tiêu dùng", "Nó có thể thất bại trong việc nhận diện nhu cầu đối với các sản phẩm mới lạ hoặc mang tính đột phá/gián đoạn"], "q": "Hạn chế nào của nghiên cứu thị trường được bộc lộ khi một sản phẩm mới ban đầu bị từ chối nhưng sau đó lại trở nên thành công rực rỡ?"}, {"a": 3, "o": ["Thử nghiệm các sản phẩm rất lớn hoặc đắt tiền tại một địa điểm tập trung", "So sánh trực tiếp các sản phẩm trong các thử nghiệm theo cặp", "Đo lường hiệu suất sử dụng sản phẩm lâu dài tại hộ gia đình", "Đánh giá ý định mua hàng của người tiêu dùng (purchase intent)"], "q": "Trong nghiên cứu người tiêu dùng giai đoạn đầu, mục đích chính của việc thử nghiệm một khái niệm sản phẩm (product concept) là gì?"}, {"a": 3, "o": ["Khi mỗi người trả lời chỉ được giao duy nhất một sản phẩm để dùng thử", "Khi người tiêu dùng được tuyển chọn và thử nghiệm tại một hội trường hoặc cửa hàng lưu động", "Khi sản phẩm phải được sử dụng tại nhà của khách hàng để đánh giá hiệu suất thông thường", "Khi sản phẩm quá lớn, đắt tiền hoặc phức tạp để có thể mang đến tận nơi cho người tiêu dùng"], "q": "Việc đưa một mẫu người tiêu dùng đại diện đến một cơ sở thử nghiệm tập trung (central facility) phù hợp nhất với tình huống nào?"}, {"a": 3, "o": ["Mỗi người tham gia so sánh hai hoặc nhiều sản phẩm và nêu ra sự ưu tiên", "Người tham gia mang sản phẩm về nhà sử dụng trong một thời gian và báo cáo trải nghiệm", "Người tham gia được đưa đến một địa điểm thử nghiệm tập trung để kiểm tra sản phẩm", "Mỗi người tham gia chỉ dùng thử duy nhất một sản phẩm và đưa ra ý kiến đánh giá của mình"], "q": "Quy trình nào mô tả đúng nhất cách thức tiến hành các thử nghiệm đơn lẻ (monadic tests)?"}, {"a": 1, "o": ["Trung tâm thử nghiệm (Test centres)", "Thử nghiệm đặt tại hộ gia đình (In-home placement tests)", "Thử nghiệm đơn lẻ (Monadic tests)", "Thử nghiệm tại hội trường / cửa hàng lưu động (Hall tests/mobile shops)"], "q": "Phương pháp nào bao gồm việc giao sản phẩm cho người tham gia sử dụng tại nhà trong điều kiện sinh hoạt bình thường và sau đó thu thập phản hồi qua bảng câu hỏi?"}, {"a": 1, "o": ["Thử và sai (Trial-and-error): tung ra nhiều biến thể mà không nghiên cứu thị trường trước", "Thị trường kéo (Market-pull): thiết kế để đáp ứng các nhu cầu do khách hàng nêu ra thông qua nghiên cứu sâu rộng", "Dựa trên trực giác (Intuition-driven): dựa vào các ý tưởng nội bộ mà không thử nghiệm người tiêu dùng", "Công nghệ đẩy (Technology-push): thiết kế để khai thác công nghệ mới bất kể nhu cầu của khách hàng"], "q": "Cách tiếp cận đổi mới nào nhấn mạnh vào việc nghiên cứu người tiêu dùng sâu rộng và sản xuất ra những gì khách hàng bày tỏ rằng họ muốn?"}], "15": [{"a": 3, "o": ["Để tập trung hóa việc ra quyết định tại trụ sở chính của công ty", "Để chuẩn hóa một sản phẩm duy nhất cho tất cả các thị trường toàn cầu", "Để giảm nhu cầu tham gia của ban lãnh đạo cấp cao", "Để tận dụng các góc nhìn đa dạng, kinh nghiệm và sự nhạy bén về văn hóa"], "q": "Lý do chính khiến các doanh nghiệp cần những đội ngũ phát triển sản phẩm mới toàn cầu (global NPD teams) gắn kết là gì?"}, {"a": 1, "o": ["Chiến lược định giá", "Khả năng lãnh đạo nhóm (Team leadership)", "Số lượng bằng sáng chế nắm giữ", "Địa điểm sản xuất"], "q": "Yếu tố nào sau đây được xác định là nhân tố quyết định then chốt đối với hiệu suất của nhóm phát triển sản phẩm mới (NPD)?"}, {"a": 0, "o": ["Một chuỗi các hoạt động liên kết, gắn kết chặt chẽ với nhau tạo thành một mô hình quy trình tổng quát", "Một tập hợp các nhiệm vụ độc lập được thực hiện riêng rẽ", "Một mô hình mạng lưới lý thuyết khái quát hóa", "Một trình tự tuyến tính nghiêm ngặt không có sự lặp lại"], "q": "Mô tả nào khớp nhất với cách thức quy trình phát triển sản phẩm mới được thể hiện?"}, {"a": 3, "o": ["Để tiến hành giới thiệu sản phẩm ra thị trường lần cuối và ra mắt trên toàn quốc", "Để tạo ra các mẫu thử vật lý phục vụ thử nghiệm kỹ thuật", "Để lựa chọn các quy trình sản xuất và nhà máy sản xuất", "Để xây dựng nền tảng tri thức của doanh nghiệp nhằm thúc đẩy sự sáng tạo và các ý tưởng sản phẩm"], "q": "Mục đích chính của việc tập hợp tri thức (assembling knowledge) trong quy trình phát triển sản phẩm mới là gì?"}, {"a": 0, "o": ["Hình thức (Form), công nghệ (technology) và nhu cầu (need)", "Thiết kế, công nghệ và giá cả", "Hình thức, chức năng và lợi ích", "Công nghệ, thị trường và chi phí"], "q": "Ba yếu tố nào là cần thiết để một ý tưởng sản phẩm (product idea) trở thành một khái niệm sản phẩm mới (new product concept)?"}, {"a": 2, "o": ["Đưa ra các quyết định ra mắt cuối cùng và kế hoạch quảng cáo", "Chỉ xác nhận tính khả thi về mặt kỹ thuật của từng ý tưởng", "Chọn lọc những ý tưởng có khả năng thành công và loại bỏ những ý tưởng không khả thi", "Phát triển các mẫu thử vật lý chi tiết cho tất cả các ý tưởng"], "q": "Mục đích chính của việc sàng lọc các ý tưởng sản phẩm (screening product ideas) trong phát triển sản phẩm mới là gì?"}, {"a": 3, "o": ["Các sản phẩm công nghiệp", "Ngành dược phẩm", "Ngành điện tử", "Các ngành thực phẩm và đồ uống (Food and drinks industries)"], "q": "Ngành công nghiệp nào có nhiều khả năng nhấn mạnh vào các hoạt động tiếp thị (marketing) hơn là các hoạt động công nghệ trong phát triển sản phẩm mới?"}, {"a": 3, "o": ["Sự phụ thuộc lớn hơn vào các hoạt động chức năng riêng lẻ", "Giảm sự giao tiếp giữa các phòng ban", "Các nhóm luôn chỉ bao gồm nhân sự chuyên trách toàn thời gian", "Gia tăng tính sáng tạo và rút ngắn thời gian phát triển sản phẩm"], "q": "Kết quả nào thường gắn liền với các nhóm đa chức năng (gồm các thành viên đến từ nhiều phòng ban chức năng khác nhau) trong các dự án sản phẩm mới?"}, {"a": 1, "o": ["Loại bỏ nhu cầu về các hoạt động chức năng đặc thù cho từng sản phẩm", "Nâng cao hiệu quả và tạo điều kiện chuyển giao công nghệ giữa các nhóm sản phẩm", "Ngăn chặn việc sử dụng các nền tảng sản phẩm chung", "Giảm số lượng các cấp quản lý cấp cao"], "q": "Lợi thế chính của việc tập trung hóa các chức năng R&D xuyên suốt các nhóm sản phẩm là gì?"}, {"a": 1, "o": ["Tích hợp các dự án kinh doanh mới vào hệ thống hoạch định và kiểm soát thông thường của doanh nghiệp", "Trao cho các đơn vị kinh doanh non trẻ sự tự do để phát triển nằm ngoài những ràng buộc thông thường của doanh nghiệp mẹ", "Chỉ thành lập một tổ chức nội bộ riêng biệt khi sản phẩm phù hợp với các hoạt động hiện có", "Chủ yếu dựa vào các nhà đầu tư mạo hiểm bên ngoài để quản lý các hoạt động kinh doanh mới"], "q": "Mô tả nào khớp nhất với hoạt động \"đầu tư mạo hiểm nội bộ doanh nghiệp\" (corporate venturing)?"}]};
